CREATE TABLE users (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL CHECK (role IN ('ADMIN','MANAGER','EMPLOYEE')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE projects (id UUID PRIMARY KEY, name VARCHAR(160) NOT NULL UNIQUE, description TEXT, location VARCHAR(255) NOT NULL, city VARCHAR(100) NOT NULL, state VARCHAR(100) NOT NULL, project_type VARCHAR(20) NOT NULL CHECK (project_type IN ('APARTMENT','VILLA','PLOT','MIXED')), status VARCHAR(20) NOT NULL CHECK (status IN ('PLANNED','ACTIVE','COMPLETED','ON_HOLD')), start_date DATE, expected_completion_date DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE towers (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, name VARCHAR(120) NOT NULL, number_of_floors INTEGER NOT NULL CHECK (number_of_floors > 0), description TEXT, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(project_id,name));
CREATE TABLE floors (id UUID PRIMARY KEY, tower_id UUID NOT NULL REFERENCES towers(id) ON DELETE RESTRICT, floor_number INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(tower_id,floor_number));
CREATE TABLE units (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, tower_id UUID NOT NULL REFERENCES towers(id) ON DELETE RESTRICT, floor_id UUID NOT NULL REFERENCES floors(id) ON DELETE RESTRICT, unit_number VARCHAR(80) NOT NULL, property_type VARCHAR(20) NOT NULL CHECK (property_type IN ('APARTMENT','VILLA','PLOT')), bedrooms INTEGER NOT NULL CHECK (bedrooms >= 0), bathrooms INTEGER NOT NULL CHECK (bathrooms >= 0), area NUMERIC(12,2) NOT NULL CHECK (area > 0), facing VARCHAR(80), base_price NUMERIC(15,2) NOT NULL CHECK (base_price >= 0), current_price NUMERIC(15,2) NOT NULL CHECK (current_price >= 0), status VARCHAR(20) NOT NULL CHECK (status IN ('AVAILABLE','BLOCKED','BOOKED','SOLD')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(tower_id,unit_number));
CREATE INDEX idx_units_filters ON units(project_id,tower_id,floor_id,status);
